-- Diary (restricted) cell (diary), generated by solo-cell-kit from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA diary;

CREATE FUNCTION diary.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE diary.journal (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    entry_type               text CHECK (entry_type IS NULL OR (entry_type IN ('daily', 'weekly', 'monthly', 'lesson', 'idea', 'reflection'))),
    title                    text NOT NULL CHECK (length(title) >= 1),
    content                  text NOT NULL CHECK (length(content) >= 1),
    tags                     text,
    related_skill_ids        text,
    related_asset_ids        text,
    mood                     integer,
    energy_level             integer,
    entry_date               date NOT NULL,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX journal_legacy ON diary.journal (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX journal_entry_type ON diary.journal (workspace_id, entry_type);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE diary.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('journal-entry')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE diary.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON diary.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['journal', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE diary.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE diary.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON diary.%I'
                       ' USING (workspace_id = diary.current_workspace())'
                       ' WITH CHECK (workspace_id = diary.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA diary TO diary_api;
GRANT EXECUTE ON FUNCTION diary.current_workspace() TO diary_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON diary.journal TO diary_api;
GRANT USAGE ON SEQUENCE diary.journal_id_seq TO diary_api;
GRANT SELECT, INSERT ON diary.create_keys TO diary_api;
GRANT SELECT, INSERT ON diary.outbox TO diary_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON diary.outbox TO diary_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON diary.outbox TO diary_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA diary TO diary_publisher;
GRANT SELECT ON diary.outbox TO diary_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON diary.outbox TO diary_publisher;
